// Adapter: the rule below is the same JavaScript as the recipe's n8n build.
// $('Step name') answers from this step's inputs: each is that step's output in this scenario.
const SOURCES = {"Config": "in0_Config", "Read the draft": "in1_Readthedraft"};
const LISTS = [];
const EXECUTED = [];
const DATA = {};
for (const [node, key] of Object.entries(SOURCES)) {
  const raw = input[key];
  let v = raw;
  if (typeof raw === 'string') { try { v = JSON.parse(raw); } catch (e) { v = raw; } }
  DATA[node] = LISTS.includes(node) ? (v || []).map(i => (i && i.json !== undefined ? i : { json: i })) : [{ json: v }];
}
const $ = (node) => {
  const ran = node in DATA || EXECUTED.includes(node);
  const list = () => { if (!(node in DATA)) throw new Error(`step ${node} has no data in this scenario`); return DATA[node]; };
  return { isExecuted: ran, first: () => list()[0], last: () => list()[list().length - 1], all: () => list(),
           get item() { return list()[0]; } };
};
const INPUT = "Read the draft";
const $input = { all: () => $(INPUT).all(), first: () => $(INPUT).first(), last: () => $(INPUT).last(), get item() { return $(INPUT).first(); } };
const $execution = { id: input.run_id };
// n8n's "Which event?": this scenario's trigger, and its body.
DATA['Which event?'] = [{ json: { event: 'verify', body: { "week": input.t_week, "sentence": input.t_sentence, "action": input.t_action, "by": input.t_by } } }];
const BODIES = (out) => ({"week_q": encodeURIComponent(out.week || ''), "patch_body": JSON.stringify(out.patch), "log_body": JSON.stringify({ recipe: 'R12.2', item: out.week + ':' + out.version + ':sentence ' + out.n, decision: out.decision + ' by ' + out.by, rules: { sentence: out.n } }), "preread_body": JSON.stringify(out.preread), "failed_body": JSON.stringify({ recipe: 'R12.2', item: 'verify', reason: 'write failed', detail: 'A verification or publication write failed; check the draft and pre-read', owner: $('Config').first().json.verifier })});
const one = (r) => (Array.isArray(r) ? r : [r]).filter(Boolean).map(i => (i.json !== undefined ? i.json : i));
const $json = INPUT && INPUT in DATA ? $input.first().json : {};
const __rule = () => {
// Step 12: the verifier approves or deletes each sentence; the backup verifier takes the verifier's own
// measures, and every sentence once Friday 16:00 has passed.
const cfg = $('Config').first().json;
const b = $('Which event?').first().json.body;
const d = ($('Read the draft').first().json.items || [])[0];
if (!d || !['to verify', 'backup'].includes(d.stage) || !['approve', 'delete'].includes(b.action)) return [];
const s = d.sentences.find(x => x.n === Number(b.sentence));
if (!s || s.decision) return [];
const own = s.measures.some(m => cfg.verifier_own_measures.includes(m));
const allowed = d.stage === 'backup' ? b.by === cfg.backup_verifier : (own ? b.by === cfg.backup_verifier : b.by === cfg.verifier);
if (!allowed) return [];
const sentences = d.sentences.map(x => x.n === s.n ? Object.assign({}, x, { decision: b.action === 'approve' ? 'approved' : 'deleted', by: b.by }) : x);
const complete = sentences.every(x => x.decision);
const narrative = sentences.filter(x => x.decision === 'approved').map(x => x.linked);
return [{ json: { week: d.week, version: d.version, n: s.n, decision: b.action === 'approve' ? 'approved' : 'deleted', by: b.by, complete,
  patch: { sentences, stage: complete ? 'published' : d.stage },
  preread: { id: d.week, week: d.week, version: d.version, table: d.table, commentary: d.commentary,
             narrative: narrative.length ? narrative : null, note: narrative.length ? 'verified' : 'no narrative this week' } } }];
};
const out = one(__rule())[0] || {};
return Object.assign({}, out, BODIES(out));
